<script setup>
import {ref} from 'vue';import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
const saved=ref(false);const site=ref({name:'Curly',tagline:'写作、分享与发现',url:'https://example.com',language:'zh-CN',postsPerPage:10,registration:false})
function save(){saved.value=true;setTimeout(()=>saved.value=false,1800)}
</script><template><AdminPageHeader title="设置" description="站点级配置。高级选项应该待在需要它们的地方，而不是堆在首页。"><template #actions><button class="primary-button pressable" @click="save">保存设置</button></template></AdminPageHeader><div class="settings-grid"><section class="surface group"><h2>站点</h2><label>站点名称<input v-model="site.name"></label><label>副标题<input v-model="site.tagline"></label><label>站点 URL<input v-model="site.url"></label></section><section class="surface group"><h2>内容</h2><label>语言<select v-model="site.language"><option value="zh-CN">简体中文</option><option value="en">English</option></select></label><label>每页文章数<input type="number" v-model.number="site.postsPerPage"></label><label class="switch-row"><span><b>开放注册</b><small>允许访客创建账户</small></span><input type="checkbox" v-model="site.registration"></label></section><section class="surface group danger"><h2>危险区域</h2><p>清空缓存、重建索引、删除站点等不可逆操作应该在这里明确隔离。</p><button class="danger-btn">重建站点索引</button></section></div><div v-if="saved" class="toast glass">设置已保存（当前为前端预览）</div></template>
<style scoped>.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.group{padding:22px;border-radius:20px}.group h2{margin:0 0 20px;letter-spacing:-.03em}.group label{display:grid;gap:7px;margin-bottom:15px;color:var(--text-2);font-size:.88rem}.group input:not([type=checkbox]),.group select{min-height:44px;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft);color:var(--text-1);padding:0 12px}.switch-row{display:flex!important;justify-content:space-between;align-items:center}.switch-row span{display:grid}.switch-row small{color:var(--text-3)}.danger{grid-column:1/-1}.danger p{color:var(--text-2);line-height:1.65}.danger-btn{border:1px solid color-mix(in srgb,var(--danger) 45%,transparent);background:transparent;color:var(--danger);border-radius:12px;padding:10px 13px;cursor:pointer}.toast{position:fixed;right:24px;bottom:24px;padding:13px 16px;border-radius:14px;z-index:100}@media(max-width:760px){.settings-grid{grid-template-columns:1fr}.danger{grid-column:auto}}</style>
